import React, { useEffect, useRef } from 'react';
import { STATUS_CONFIG } from './UIKit';

// Use raw leaflet (no react-leaflet to keep it simple)
export default function FleetMap({ fleet, selectedVehicle, onSelectVehicle }) {
  const mapRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const markersRef = useRef({});

  useEffect(() => {
    if (!mapRef.current || mapInstanceRef.current) return;

    // Dynamic import of Leaflet
    import('leaflet').then(L => {
      // Fix marker icons
      delete L.Icon.Default.prototype._getIconUrl;
      L.Icon.Default.mergeOptions({
        iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon-2x.png',
        iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon.png',
        shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png',
      });

      const map = L.map(mapRef.current, {
        center: [37.762, -122.435],
        zoom: 13,
        zoomControl: false,
      });

      L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
        attribution: '©OpenStreetMap ©CartoDB',
        maxZoom: 19,
      }).addTo(map);

      L.control.zoom({ position: 'bottomright' }).addTo(map);

      mapInstanceRef.current = { map, L };
    });

    return () => {
      if (mapInstanceRef.current) {
        mapInstanceRef.current.map.remove();
        mapInstanceRef.current = null;
      }
    };
  }, []);

  // Update markers when fleet changes
  useEffect(() => {
    if (!mapInstanceRef.current || !fleet.length) return;
    const { map, L } = mapInstanceRef.current;

    fleet.forEach(vehicle => {
      const cfg = STATUS_CONFIG[vehicle.status] || STATUS_CONFIG.idle;
      const isSelected = selectedVehicle?.id === vehicle.id;

      const svgIcon = `
        <svg xmlns="http://www.w3.org/2000/svg" width="${isSelected ? 44 : 36}" height="${isSelected ? 44 : 36}" viewBox="0 0 36 36">
          <circle cx="18" cy="18" r="${isSelected ? 17 : 14}" fill="${cfg.color}22" stroke="${cfg.color}" stroke-width="${isSelected ? 2.5 : 1.5}"/>
          <circle cx="18" cy="18" r="8" fill="${cfg.color}" opacity="0.9"/>
          <text x="18" y="22" text-anchor="middle" font-size="9" fill="#000" font-weight="bold" font-family="monospace">${vehicle.id.slice(-3)}</text>
        </svg>
      `;

      const icon = L.divIcon({
        html: svgIcon,
        className: '',
        iconSize: [isSelected ? 44 : 36, isSelected ? 44 : 36],
        iconAnchor: [isSelected ? 22 : 18, isSelected ? 22 : 18],
      });

      if (markersRef.current[vehicle.id]) {
        markersRef.current[vehicle.id]
          .setLatLng([vehicle.lat, vehicle.lng])
          .setIcon(icon);
      } else {
        const marker = L.marker([vehicle.lat, vehicle.lng], { icon })
          .addTo(map)
          .on('click', () => onSelectVehicle(vehicle));
        markersRef.current[vehicle.id] = marker;
      }

      markersRef.current[vehicle.id]
        .bindTooltip(
          `<b>${vehicle.id}</b><br/>${cfg.label}<br/>${Math.round(vehicle.speed)} km/h`,
          { className: 'fleet-tooltip', direction: 'top', offset: [0, -10] }
        );
    });
  }, [fleet, selectedVehicle, onSelectVehicle]);

  return (
    <div style={{ position: 'relative', height: '100%', borderRadius: 12, overflow: 'hidden' }}>
      <div ref={mapRef} style={{ height: '100%', width: '100%', borderRadius: 12 }} />
      <style>{`
        .leaflet-container { background: #0a0e1a; font-family: monospace; }
        .fleet-tooltip { background: #0f1525; border: 1px solid #1e3a5f; color: #e0eaff; font-family: monospace; font-size: 11px; padding: 6px 10px; border-radius: 6px; }
        .fleet-tooltip::before { display: none; }
      `}</style>
    </div>
  );
}
